// @ts-nocheck -- UI component; API routes enforce server-side validation.
'use client';
import {useEffect,useMemo,useState} from 'react';
import QRCode from 'qrcode';
import PasswordForm from './password-form';

type User={id:number;email:string;name:string;lastName:string;phone:string;role:'USER'|'ADMIN'};
type Product={id:number;sku?:string;image:string;name:string;category:string;brand:string;description:string;price:number;old:number;rating:number;stock:number;room:string;status?:string};
type Address={id:number;label:string;recipient_name:string;phone:string;address_line:string;district:string;province:string;postal_code:string;is_default:number};

const fallback:Product[]=[
  {id:1,sku:'LUMA-E27',image:'/products/smart-bulb.png',name:'Philips Hue Smart Bulb E26',category:'Smart Lighting',brand:'Philips Hue',description:'หลอดไฟอัจฉริยะปรับสีและความสว่าง ควบคุมผ่านแอปและคำสั่งเสียง',price:790,old:990,rating:4.9,stock:42,room:'ห้องนอน'},
  {id:2,sku:'AEGIS-2K',image:'/products/smart-camera.jpg',name:'TP-Link Tapo C210 2K',category:'Smart Camera',brand:'TP-Link',description:'กล้อง 2K หมุน 360° ตรวจจับการเคลื่อนไหวและสนทนาโต้ตอบ',price:1890,old:2290,rating:4.8,stock:12,room:'หน้าบ้าน'},
  {id:3,sku:'NEXA-PRO',image:'/products/smart-lock.png',name:'Yale Assure Smart Lock',category:'Smart Door Lock',brand:'Yale',description:'กลอนประตูอัจฉริยะ ปลดล็อกด้วย PIN และควบคุมผ่านสมาร์ตโฟน',price:4590,old:5290,rating:4.9,stock:4,room:'หน้าบ้าน'},
  {id:4,sku:'TAPO-P100',image:'/products/smart-plug.jpg',name:'TP-Link Tapo P100',category:'Smart Plug',brand:'TP-Link',description:'ปลั๊ก Wi-Fi ตั้งเวลาและควบคุมเครื่องใช้ไฟฟ้าจากระยะไกล',price:590,old:690,rating:4.7,stock:67,room:'ห้องทำงาน'},
];
const rooms=['ห้องนอน','ห้องนั่งเล่น','ห้องครัว','ห้องน้ำ','ห้องทำงาน','หน้าบ้าน'];
const categories=[['💡','Smart Lighting'],['📷','Smart Camera'],['🔐','Smart Door Lock'],['🔌','Smart Plug'],['🔊','Smart Speaker'],['◉','Smart Sensor'],['🌬️','Smart Appliance'],['🪟','Smart Curtain'],['🍳','Smart Kitchen'],['🔔','Smart Doorbell']];

function SiteHeader({user,cartCount}:{user:User|null;cartCount:number}){
  async function logout(){await fetch('/api/logout',{method:'POST'});window.location.assign('/')}
  return <><div className="site-promo">ส่งฟรีเมื่อช้อปครบ ฿1,500 <span>•</span> รับประกันสินค้าแท้ทุกชิ้น</div><header className="site-header"><div className="site-header-inner"><a href="/" aria-label="หน้าแรก"><img src="/smart-home-store-logo.png" alt="Smart Home Store" className="site-logo"/></a><nav className="site-desktop-nav"><a href="/products">สินค้า</a><a href="/recommendations" className="featured">ช่วยเลือกสินค้า</a><a href="/rooms">เลือกตามห้อง</a><a href="/smart-home-sets">Smart Home Set</a><a href="/promotions">โปรโมชั่น</a></nav><div className="site-actions">{user?<><a href="/profile" className="site-user"><span className="site-user-avatar">{user.name.slice(0,1)}</span><span>{user.name}</span></a>{user.role==='ADMIN'&&<a href="/admin" className="site-admin-link">หลังบ้าน</a>}<button onClick={logout} className="site-logout">ออกจากระบบ</button></>:<><a href="/login" className="site-login">เข้าสู่ระบบ</a><a href="/register" className="site-register">สมัครสมาชิก</a></>}<a href="/favorites" className="site-icon" aria-label="รายการโปรด">♡</a><a href="/cart" className="site-icon site-cart" aria-label="ตะกร้า">🛒{cartCount>0&&<span>{cartCount}</span>}</a></div></div></header><nav className="site-mobile-nav" aria-label="เมนูหลักบนมือถือ"><a href="/">⌂<span>หน้าหลัก</span></a><a href="/products">⌕<span>สินค้า</span></a><a href="/recommendations">◇<span>ช่วยเลือก</span></a><a href="/rooms">▦<span>ห้อง</span></a><a href={user?'/profile':'/login'}>◯<span>{user?'บัญชี':'เข้าสู่ระบบ'}</span></a></nav></>
}

function Title({title,subtitle}:{title:string;subtitle:string}){return <div className="section-title"><div><p>CURATED SMART LIVING</p><h1>{title}</h1></div><span>{subtitle}</span></div>}

function ProductCard({product,onAdd,favorite,onFavorite}:{product:Product;onAdd:(p:Product)=>void;favorite:boolean;onFavorite:(p:Product)=>void}){const discount=product.old>product.price?Math.round((1-product.price/product.old)*100):0;return <article className="product-card"><div className="product-media"><a href={`/products/${product.id}`}><img src={product.image} alt={product.name}/></a><span className="product-badge">{discount?`-${discount}%`:'แนะนำ'}</span><button onClick={()=>onFavorite(product)} aria-label={favorite?`นำ ${product.name} ออกจากรายการโปรด`:`เพิ่ม ${product.name} ในรายการโปรด`} className={favorite?'favorite active':'favorite'}>{favorite?'♥':'♡'}</button></div><div className="product-body"><div className="product-meta"><span>{product.category}</span><i>{product.stock>0?'พร้อมส่ง':'สินค้าหมด'}</i></div><a href={`/products/${product.id}`}><h3>{product.name}</h3></a><p>{product.description}</p><div className="product-rating"><span>★★★★★</span> {product.rating}</div><div className="product-buy"><div><b>฿{product.price.toLocaleString()}</b>{product.old>product.price&&<del>฿{product.old.toLocaleString()}</del>}</div><button disabled={product.stock<1} onClick={()=>onAdd(product)} aria-label={`เพิ่ม ${product.name} ลงตะกร้า`}><span>＋</span> เพิ่ม</button></div></div></article>}

function PasswordEye({visible}:{visible:boolean}){return <svg aria-hidden="true" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.8" strokeLinecap="round" strokeLinejoin="round" className="h-5 w-5"><path d="M2.5 12s3.5-6 9.5-6 9.5 6 9.5 6-3.5 6-9.5 6-9.5-6-9.5-6Z"/><circle cx="12" cy="12" r="2.5"/>{visible&&<path d="m4 4 16 16"/>}</svg>}

function RegisterForm(){
  const[loading,setLoading]=useState(false),[message,setMessage]=useState(''),[password,setPassword]=useState(''),[showPassword,setShowPassword]=useState(false),[showConfirmPassword,setShowConfirmPassword]=useState(false);
  const letterCount=(password.match(/[A-Za-z]/g)||[]).length;
  const passwordValid=password.length>=8&&letterCount>=1;
  async function submit(e){
    e.preventDefault();setLoading(true);setMessage('');
    const form=new FormData(e.currentTarget);
    if(!passwordValid){setMessage('รหัสผ่านต้องมีอย่างน้อย 8 ตัว และมีอักษรอังกฤษอย่างน้อย 1 ตัว');setLoading(false);return}
    if(form.get('password')!==form.get('confirmPassword')){setMessage('รหัสผ่านและการยืนยันไม่ตรงกัน');setLoading(false);return}
    const res=await fetch('/api/register',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify(Object.fromEntries(form.entries()))});
    const data=await res.json();
    if(res.ok){setMessage('สมัครสมาชิกสำเร็จ กำลังไปหน้าเข้าสู่ระบบ...');setTimeout(()=>window.location.assign('/login?registered=1'),600);return}
    setMessage(data.error||'ไม่สามารถสมัครสมาชิกได้');setLoading(false)
  }
  const fieldClass="mt-2 w-full rounded-xl border border-slate-200 bg-slate-50/70 px-4 py-3 font-normal text-slate-900 placeholder:text-slate-400";
  return <div className="minimal-card overflow-hidden rounded-[1.75rem]">
    <div className="grid lg:grid-cols-[.82fr_1.18fr]">
      <aside className="relative min-h-[420px] overflow-hidden bg-slate-900 p-8 text-white lg:min-h-full">
        <img src="/hero-minimal-smart-home.png" alt="ห้อง Smart Home สไตล์มินิมอล" className="absolute inset-0 h-full w-full object-cover opacity-45"/>
        <div className="absolute inset-0 bg-gradient-to-t from-slate-950 via-slate-900/65 to-slate-800/20"></div>
        <div className="relative flex h-full flex-col justify-between">
          <img src="/smart-home-store-logo.png" alt="Smart Home Store" className="w-44 rounded-xl bg-white p-2"/>
          <div className="mt-24"><p className="text-xs font-bold tracking-[.16em] text-cyan-300">SMART HOME MEMBER</p><h2 className="mt-3 text-3xl font-bold tracking-[-.02em]">ทุกอย่างของบ้าน<br/>อยู่ในบัญชีเดียว</h2><p className="mt-4 max-w-sm text-sm leading-7 text-slate-200">บันทึกสินค้า ติดตามคำสั่งซื้อ และจัดการที่อยู่จัดส่งได้อย่างสะดวก</p><ul className="mt-6 grid gap-3 text-sm text-white/90"><li>✓ บันทึกรายการโปรด</li><li>✓ ติดตามสถานะจัดส่ง</li><li>✓ จัดการที่อยู่และประวัติคำสั่งซื้อ</li></ul></div>
        </div>
      </aside>
      <form onSubmit={submit} className="bg-white p-7 sm:p-10">
        <p className="text-[11px] font-bold tracking-[.18em] text-blue-600">CREATE ACCOUNT</p><h1 className="mt-2 text-3xl font-bold tracking-[-.025em] text-slate-900">สร้างบัญชีใหม่</h1><p className="mb-7 mt-2 text-sm text-slate-500">ใช้เวลาไม่ถึง 2 นาที และแก้ไขข้อมูลได้ภายหลัง</p>
        <div className="grid gap-4 sm:grid-cols-2">
          <label className="text-sm font-bold text-slate-700">ชื่อ<input name="firstName" required autoComplete="given-name" className={fieldClass}/></label>
          <label className="text-sm font-bold text-slate-700">นามสกุล<input name="lastName" required autoComplete="family-name" className={fieldClass}/></label>
          <label className="text-sm font-bold text-slate-700 sm:col-span-2">ชื่อผู้ใช้<input name="username" required minLength={4} autoComplete="username" placeholder="อย่างน้อย 4 ตัวอักษร" className={fieldClass}/></label>
          <label className="text-sm font-bold text-slate-700 sm:col-span-2">อีเมล<input name="email" required type="email" autoComplete="email" placeholder="name@example.com" className={fieldClass}/></label>
          <label className="text-sm font-bold text-slate-700 sm:col-span-2">เบอร์โทรศัพท์<input name="phone" required inputMode="numeric" pattern="[0-9]{9,10}" autoComplete="tel" placeholder="0812345678" aria-describedby="phone-help" className={fieldClass}/><span id="phone-help" className="mt-1.5 block text-xs font-normal text-slate-400">ตัวอย่าง: 0812345678 (กรอกเฉพาะตัวเลข 9–10 หลัก)</span></label>
          <label className="text-sm font-bold text-slate-700">รหัสผ่าน<div className="relative"><input name="password" required type={showPassword?'text':'password'} minLength={8} autoComplete="new-password" value={password} onChange={event=>setPassword(event.target.value)} placeholder="เช่น SmartHome123" aria-describedby="password-help" className={`${fieldClass} pr-14`}/><button type="button" onClick={()=>setShowPassword(value=>!value)} aria-pressed={showPassword} aria-label={showPassword?'ซ่อนรหัสผ่าน':'แสดงรหัสผ่าน'} title={showPassword?'ซ่อนรหัสผ่าน':'แสดงรหัสผ่าน'} className="absolute bottom-2 right-2 grid h-9 w-9 place-items-center rounded-full text-slate-500 hover:bg-slate-200/70 hover:text-slate-800"><PasswordEye visible={showPassword}/></button></div></label>
          <label className="text-sm font-bold text-slate-700">ยืนยันรหัสผ่าน<div className="relative"><input name="confirmPassword" required type={showConfirmPassword?'text':'password'} minLength={8} autoComplete="new-password" placeholder="กรอกรหัสผ่านอีกครั้ง" className={`${fieldClass} pr-14`}/><button type="button" onClick={()=>setShowConfirmPassword(value=>!value)} aria-pressed={showConfirmPassword} aria-label={showConfirmPassword?'ซ่อนรหัสผ่านยืนยัน':'แสดงรหัสผ่านยืนยัน'} title={showConfirmPassword?'ซ่อนรหัสผ่านยืนยัน':'แสดงรหัสผ่านยืนยัน'} className="absolute bottom-2 right-2 grid h-9 w-9 place-items-center rounded-full text-slate-500 hover:bg-slate-200/70 hover:text-slate-800"><PasswordEye visible={showConfirmPassword}/></button></div></label>
          <div id="password-help" aria-live="polite" className="sm:col-span-2 rounded-xl border border-slate-200 bg-slate-50 p-4 text-xs">
            <p className="font-bold text-slate-700">เงื่อนไขรหัสผ่าน</p><div className="mt-2 grid gap-2 sm:grid-cols-2"><span className={password.length>=8?'text-emerald-600':'text-slate-500'}>{password.length>=8?'✓':'○'} ความยาว {password.length}/8 ตัว</span><span className={letterCount>=1?'text-emerald-600':'text-slate-500'}>{letterCount>=1?'✓':'○'} อักษรอังกฤษ {letterCount} ตัว</span></div>
          </div>
        </div>
        <fieldset className="mt-6 space-y-3"><legend className="mb-3 text-sm font-bold text-slate-900">การยินยอมและความเป็นส่วนตัว</legend>
          <label className="flex cursor-pointer gap-3 rounded-xl border border-slate-200 bg-slate-50/70 p-4 text-sm leading-6 text-slate-600"><input name="privacyConsent" type="checkbox" required className="mt-1 h-4 w-4 shrink-0 accent-blue-600"/><span><b className="text-slate-900">จำเป็นสำหรับการสมัครสมาชิก</b><br/>ฉันอ่านและยอมรับ <a href="/terms" target="_blank" className="font-bold text-blue-600 underline underline-offset-2">ข้อกำหนดการใช้งาน</a> และ <a href="/privacy" target="_blank" className="font-bold text-blue-600 underline underline-offset-2">นโยบายความเป็นส่วนตัว</a> รวมถึงรับทราบว่าร้านจะเก็บและใช้ชื่อ อีเมล เบอร์โทร และที่อยู่ เพื่อสร้างบัญชี ดำเนินคำสั่งซื้อ จัดส่งสินค้า และบริการหลังการขาย</span></label>
          <label className="flex cursor-pointer gap-3 rounded-xl border border-slate-200 p-4 text-sm leading-6 text-slate-600"><input name="marketingConsent" type="checkbox" className="mt-1 h-4 w-4 shrink-0 accent-blue-600"/><span><b className="text-slate-900">รับข่าวสารและโปรโมชั่น (ไม่บังคับ)</b><br/>ฉันยินยอมรับข่าวสาร โปรโมชั่น และข้อเสนอที่เหมาะกับฉันทางอีเมลหรือโทรศัพท์ โดยยกเลิกความยินยอมได้ทุกเมื่อ</span></label>
        </fieldset>
        <p className="mt-3 text-xs leading-5 text-slate-400">เราใช้ข้อมูลเท่าที่จำเป็นต่อการให้บริการ ไม่ขายข้อมูลส่วนบุคคล และคุณสามารถขอเข้าถึง แก้ไข หรือลบข้อมูลได้ตามช่องทางในนโยบายความเป็นส่วนตัว</p>
        {message&&<p role="status" className={`mt-5 rounded-xl p-3 text-sm ${message.includes('สำเร็จ')?'bg-green-50 text-green-700':'bg-red-50 text-red-600'}`}>{message}</p>}
        <button disabled={loading} className="mt-6 w-full rounded-xl bg-blue-600 py-4 font-bold text-white shadow-sm transition hover:bg-blue-700 disabled:opacity-60">{loading?'กำลังสมัคร...':'สมัครสมาชิก'}</button><p className="mt-5 text-center text-sm text-slate-500">มีบัญชีแล้ว? <a href="/login" className="font-bold text-blue-600">เข้าสู่ระบบ</a></p>
      </form>
    </div>
  </div>
}

function LoginForm(){
  const[error,setError]=useState(''),[returnTo,setReturnTo]=useState('/'),[showPassword,setShowPassword]=useState(false);
  useEffect(()=>{const p=new URLSearchParams(window.location.search);setReturnTo(p.get('returnTo')||'/');const code=p.get('error');if(code==='invalid')setError('อีเมลหรือรหัสผ่านไม่ถูกต้อง');else if(code==='server')setError('ระบบเข้าสู่ระบบขัดข้อง กรุณาลองใหม่');else if(code==='required')setError('กรุณาเข้าสู่ระบบก่อนใช้งานหน้านี้')},[]);
  return <div className="auth-login"><aside><img src="/hero-minimal-smart-home.png" alt="บ้านอัจฉริยะสไตล์มินิมอล"/><div className="auth-login-overlay"/><img className="auth-login-logo" src="/smart-home-store-logo.png" alt="Smart Home Store"/><div className="auth-login-copy"><span>WELCOME HOME</span><h1>จัดการบ้านของคุณ<br/>ได้ง่ายกว่าเดิม</h1><p>เข้าสู่ระบบเพื่อดูรายการโปรด ที่อยู่ คำสั่งซื้อ และสถานะการจัดส่งในที่เดียว</p></div></aside><form action="/api/login" method="post"><input type="hidden" name="returnTo" value={returnTo}/><p className="auth-kicker">SECURE MEMBER ACCESS</p><h2>ยินดีต้อนรับกลับ</h2><span className="auth-subtitle">กรอกข้อมูลบัญชีเพื่อเข้าสู่ Smart Home Store</span><div className="auth-fields"><label>อีเมล<input name="email" required type="email" autoComplete="email" placeholder="name@example.com"/></label><label>รหัสผ่าน<div><input name="password" required type={showPassword?'text':'password'} autoComplete="current-password" placeholder="กรอกรหัสผ่าน"/><button type="button" onClick={()=>setShowPassword(value=>!value)} aria-pressed={showPassword} aria-label={showPassword?'ซ่อนรหัสผ่าน':'แสดงรหัสผ่าน'}><PasswordEye visible={showPassword}/></button></div></label></div>{error&&<p role="alert" className="auth-error">{error}</p>}<button type="submit" className="auth-submit">เข้าสู่ระบบ <span>→</span></button><div className="auth-divider"><span>ยังไม่มีบัญชีใช่ไหม?</span></div><a href="/register" className="auth-create">สร้างบัญชีใหม่</a><p className="auth-safe">🔒 ระบบจะเข้ารหัสรหัสผ่านของคุณก่อนบันทึกเสมอ</p></form></div>
}
function LegalPage({kind}:{kind:'terms'|'privacy'}){
  const privacy=kind==='privacy';
  return <section className="minimal-page px-5 py-12"><div className="minimal-card mx-auto max-w-3xl rounded-[1.75rem] p-7 sm:p-10"><p className="text-[11px] font-bold tracking-[.18em] text-blue-600">SMART HOME STORE</p><h1 className="mt-2 text-3xl font-bold text-slate-900">{privacy?'นโยบายความเป็นส่วนตัว':'ข้อกำหนดการใช้งาน'}</h1><p className="mt-3 text-sm text-slate-500">ฉบับสำหรับมินิโปรเจกต์ Smart Home Store · ปรับปรุงล่าสุด 2 กันยายน 2569</p>{privacy?<div className="mt-8 space-y-7 text-sm leading-7 text-slate-600"><section><h2 className="font-bold text-slate-900">ข้อมูลที่เราเก็บ</h2><p>ชื่อ นามสกุล ชื่อผู้ใช้ อีเมล เบอร์โทร ที่อยู่จัดส่ง รายการโปรด และข้อมูลคำสั่งซื้อที่จำเป็นต่อการให้บริการ</p></section><section><h2 className="font-bold text-slate-900">วัตถุประสงค์การใช้ข้อมูล</h2><p>เพื่อสร้างและรักษาบัญชี ดำเนินคำสั่งซื้อ จัดส่งสินค้า ให้บริการหลังการขาย ป้องกันการทุจริต และพัฒนาคุณภาพบริการ ส่วนการส่งข่าวสารหรือโปรโมชั่นจะทำเมื่อผู้ใช้เลือกยินยอมเท่านั้น</p></section><section><h2 className="font-bold text-slate-900">การเปิดเผยและระยะเวลาจัดเก็บ</h2><p>เราเปิดเผยข้อมูลเฉพาะแก่ผู้ให้บริการที่จำเป็น เช่น ผู้ให้บริการจัดส่ง และเก็บข้อมูลเท่าที่จำเป็นต่อวัตถุประสงค์หรือระยะเวลาตามกฎหมาย โดยไม่ขายข้อมูลส่วนบุคคล</p></section><section><h2 className="font-bold text-slate-900">สิทธิของผู้ใช้</h2><p>ผู้ใช้สามารถขอเข้าถึง แก้ไข ลบ จำกัดหรือคัดค้านการใช้ข้อมูล รวมถึงถอนความยินยอมด้านการตลาดได้ โดยติดต่อผู้ดูแล Smart Home Store</p></section></div>:<div className="mt-8 space-y-7 text-sm leading-7 text-slate-600"><section><h2 className="font-bold text-slate-900">การใช้บัญชี</h2><p>ผู้สมัครต้องให้ข้อมูลที่ถูกต้อง ดูแลรหัสผ่านของตน และไม่ใช้ระบบเพื่อการฉ้อโกง รบกวน หรือกระทำผิดกฎหมาย</p></section><section><h2 className="font-bold text-slate-900">สินค้า ราคา และคำสั่งซื้อ</h2><p>ข้อมูลสินค้า ราคา และสต็อกอาจเปลี่ยนแปลงได้ คำสั่งซื้อจะสมบูรณ์เมื่อระบบยืนยันรายการ และร้านอาจยกเลิกรายการที่เกิดจากข้อผิดพลาดชัดเจนหรือการใช้งานที่ไม่เหมาะสม</p></section><section><h2 className="font-bold text-slate-900">การรับประกันและข้อจำกัด</h2><p>การรับประกันเป็นไปตามเงื่อนไขของสินค้าและผู้ผลิต เว็บไซต์มินิโปรเจกต์นี้จัดทำเพื่อสาธิตระบบร้านค้าและไม่ใช่ข้อเสนอขายที่มีผลผูกพันทางกฎหมาย</p></section></div>}<a href="/register" className="mt-9 inline-flex rounded-full bg-slate-900 px-5 py-3 text-sm font-bold text-white hover:bg-blue-600">กลับไปหน้าสมัครสมาชิก</a></div></section>
}

function ProfilePage({user}:{user:User}){
  const[addresses,setAddresses]=useState<Address[]>([]),[message,setMessage]=useState('');
  async function load(){const r=await fetch('/api/addresses');if(r.ok)setAddresses((await r.json()).data)}
  useEffect(()=>{load()},[]);
  async function saveProfile(e){e.preventDefault();const body=Object.fromEntries(new FormData(e.currentTarget));const r=await fetch('/api/profile',{method:'PATCH',headers:{'content-type':'application/json'},body:JSON.stringify(body)});const d=await r.json();setMessage(d.message||d.error);if(r.ok)setTimeout(()=>location.reload(),500)}
  async function addAddress(e){e.preventDefault();const form=e.currentTarget;const r=await fetch('/api/addresses',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify(Object.fromEntries(new FormData(form)))});const d=await r.json();setMessage(d.message||d.error);if(r.ok){form.reset();await load()}}
  async function remove(id:number){if(!confirm('ต้องการลบที่อยู่นี้หรือไม่?'))return;const r=await fetch(`/api/addresses?id=${id}`,{method:'DELETE'});const d=await r.json();setMessage(d.message||d.error);if(r.ok)await load()}
  async function logout(){await fetch('/api/logout',{method:'POST'});location.assign('/login')}
  return <section className="account-page"><div className="account-hero"><div className="account-avatar">{user.name.slice(0,1)}</div><div><p>MY SMART HOME</p><h1>{user.name} {user.lastName}</h1><span>{user.email}</span></div><button onClick={logout} className="account-logout">ออกจากระบบ</button></div>{message&&<p className="account-notice" role="status">{message}</p>}<div className="account-layout"><nav className="account-nav" aria-label="ส่วนของบัญชี"><a href="#personal">ข้อมูลส่วนตัว</a><a href="#addresses">ที่อยู่จัดส่ง <b>{addresses.length}</b></a><a href="#security">ความปลอดภัย</a><a href="/favorites">รายการโปรด</a></nav><div className="account-content"><form id="personal" onSubmit={saveProfile} className="account-card"><div className="account-card-title"><span>01</span><div><h2>ข้อมูลส่วนตัว</h2><p>ข้อมูลที่ใช้ติดต่อและจัดส่งสินค้า</p></div></div><div className="account-form-grid"><label>ชื่อ<input name="firstName" defaultValue={user.name} required autoComplete="given-name"/></label><label>นามสกุล<input name="lastName" defaultValue={user.lastName} required autoComplete="family-name"/></label><label className="wide">อีเมล<input value={user.email} disabled/></label><label className="wide">เบอร์โทรศัพท์<input name="phone" defaultValue={user.phone} required inputMode="numeric" pattern="[0-9]{9,10}" placeholder="0812345678" autoComplete="tel"/><small>กรอกเฉพาะตัวเลข 9–10 หลัก</small></label></div><button className="account-primary">บันทึกข้อมูล</button></form><form id="addresses" onSubmit={addAddress} className="account-card"><div className="account-card-title"><span>02</span><div><h2>เพิ่มที่อยู่จัดส่ง</h2><p>บันทึกได้หลายที่อยู่และเลือกที่อยู่หลัก</p></div></div><div className="account-form-grid"><label>ชื่อที่อยู่<input name="label" required placeholder="เช่น บ้าน หรือ ที่ทำงาน"/></label><label>ชื่อผู้รับ<input name="recipientName" required autoComplete="name"/></label><label>เบอร์โทร<input name="phone" required inputMode="numeric" pattern="[0-9]{9,10}" placeholder="0812345678" autoComplete="tel"/></label><label>รหัสไปรษณีย์<input name="postalCode" required inputMode="numeric" pattern="[0-9]{5}" placeholder="10110" autoComplete="postal-code"/></label><label className="wide">บ้านเลขที่ ถนน ซอย<input name="addressLine" required autoComplete="street-address"/></label><label>เขต / อำเภอ<input name="district" required/></label><label>จังหวัด<input name="province" required/></label></div><label className="account-check"><input name="isDefault" type="checkbox"/>ตั้งเป็นที่อยู่หลัก</label><button className="account-secondary">เพิ่มที่อยู่</button></form><section className="address-list">{addresses.length?addresses.map(a=><article key={a.id} className="account-address"><div><span>{a.is_default?'ที่อยู่หลัก':'ที่อยู่'}</span><h3>{a.label}</h3></div><button onClick={()=>remove(a.id)} aria-label={`ลบที่อยู่ ${a.label}`}>ลบ</button><p>{a.recipient_name} · {a.phone}<br/>{a.address_line} {a.district} {a.province} {a.postal_code}</p></article>):<div className="account-empty">ยังไม่มีที่อยู่จัดส่ง</div>}</section><div id="security"><PasswordForm/></div></div></div></section>
}

function AdminPage(){const[data,setData]=useState<any>(null),[message,setMessage]=useState('');async function load(){const r=await fetch('/api/admin/dashboard');const d=await r.json();if(r.ok)setData(d);else setMessage(d.error)}useEffect(()=>{load()},[]);async function addProduct(e){e.preventDefault();const form=e.currentTarget;const r=await fetch('/api/products',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify(Object.fromEntries(new FormData(form)))});const d=await r.json();setMessage(d.message||d.error);if(r.ok){form.reset();await load()}}async function removeProduct(id){if(!confirm('ปิดการขายสินค้านี้หรือไม่?'))return;const r=await fetch(`/api/products?id=${id}`,{method:'DELETE'});setMessage((await r.json()).message||'ดำเนินการแล้ว');load()}if(!data)return <section className="p-10">{message||'กำลังโหลดระบบ Admin...'}</section>;const s=data.stats;return <section className="mx-auto max-w-7xl px-5 py-10"><div className="mb-8 flex items-center justify-between"><Title title="Admin Dashboard" subtitle="จัดการข้อมูลร้านค้าแบบเรียลไทม์"/><a href="/" className="rounded-xl border px-4 py-2">กลับหน้าร้าน</a></div>{message&&<p className="mb-5 rounded-xl bg-blue-50 p-3 text-sm text-blue-700">{message}</p>}<div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-4">{[['รายได้',`฿${Number(s.revenue).toLocaleString()}`],['คำสั่งซื้อ',s.orders],['สมาชิก',s.customers],['สินค้าใกล้หมด',s.low_stock]].map(x=><div key={x[0]} className="rounded-2xl bg-[#0B1F3A] p-6 text-white"><span className="text-sm text-slate-300">{x[0]}</span><b className="mt-2 block text-3xl">{x[1]}</b></div>)}</div><div className="mt-7 grid gap-6 lg:grid-cols-[.8fr_1.2fr]"><form onSubmit={addProduct} className="h-fit rounded-3xl border bg-white p-6"><h2 className="text-xl font-bold">เพิ่มสินค้า</h2><div className="mt-4 grid gap-3"><input name="sku" required placeholder="SKU" className="rounded-xl border p-3"/><input name="name" required placeholder="ชื่อสินค้า" className="rounded-xl border p-3"/><textarea name="description" required placeholder="คำอธิบายสินค้า" className="rounded-xl border p-3"/><div className="grid grid-cols-2 gap-3"><input name="category" required placeholder="หมวดหมู่" className="rounded-xl border p-3"/><input name="brand" required placeholder="แบรนด์" className="rounded-xl border p-3"/><input name="price" required type="number" min="1" placeholder="ราคา" className="rounded-xl border p-3"/><input name="stock" required type="number" min="0" placeholder="สต็อก" className="rounded-xl border p-3"/></div></div><button className="mt-4 w-full rounded-xl bg-blue-600 py-3 font-bold text-white">เพิ่มสินค้า</button></form><div className="overflow-hidden rounded-3xl border bg-white"><h2 className="p-6 text-xl font-bold">สินค้าในระบบ</h2><div className="overflow-x-auto"><table className="w-full text-left text-sm"><thead className="bg-slate-50"><tr><th className="p-3">SKU</th><th className="p-3">สินค้า</th><th className="p-3">สต็อก</th><th className="p-3">สถานะ</th><th/></tr></thead><tbody>{data.products.map(p=><tr key={p.id} className="border-t"><td className="p-3">{p.sku}</td><td className="p-3 font-bold">{p.name}</td><td className="p-3">{p.stock}</td><td className="p-3">{p.status}</td><td className="p-3"><button onClick={()=>removeProduct(p.id)} className="text-red-500">ปิดการขาย</button></td></tr>)}</tbody></table></div></div></div><div className="mt-7 grid gap-6 lg:grid-cols-2"><div className="overflow-hidden rounded-3xl border bg-white"><h2 className="p-6 text-xl font-bold">สมาชิกล่าสุด</h2>{data.users.map(u=><div key={u.id} className="flex justify-between border-t p-4 text-sm"><span><b>{u.first_name} {u.last_name}</b><small className="block text-slate-500">{u.email}</small></span><b>{u.role}</b></div>)}</div><div className="overflow-hidden rounded-3xl border bg-white"><h2 className="p-6 text-xl font-bold">คำสั่งซื้อล่าสุด</h2>{data.orders.length?data.orders.map(o=><div key={o.order_number} className="flex justify-between border-t p-4 text-sm"><span><b>{o.order_number}</b><small className="block text-slate-500">{o.email}</small></span><span className="text-right"><b>฿{Number(o.grand_total).toLocaleString()}</b><small className="block">{o.status}</small></span></div>):<p className="border-t p-6 text-sm text-slate-500">ยังไม่มีคำสั่งซื้อ</p>}</div></div></section>}

function RecommendationPage({products,onAdd,favorites,onFavorite}:{products:Product[];onAdd:(p:Product)=>void;favorites:number[];onFavorite:(p:Product)=>void}){
  const[purpose,setPurpose]=useState('security'),[budget,setBudget]=useState('3000'),[selectedRoom,setSelectedRoom]=useState('ห้องนั่งเล่น'),[searched,setSearched]=useState(true);
  const purposeCategories={security:['Smart Camera','Smart Door Lock','Smart Doorbell','Smart Sensor'],comfort:['Smart Speaker','Smart Curtain','Smart Appliance','Smart Plug'],energy:['Smart Lighting','Smart Plug','Smart Sensor'],kitchen:['Smart Kitchen','Smart Plug','Smart Sensor']}[purpose]||[];
  const limit=Number(budget);
  const recommendations=useMemo(()=>products.filter(product=>purposeCategories.includes(product.category)&&product.price<=limit&&(selectedRoom==='ทุกห้อง'||product.room===selectedRoom)).sort((a,b)=>b.rating-a.rating||a.price-b.price).slice(0,4),[products,purpose,budget,selectedRoom]);
  return <section className="mx-auto max-w-7xl px-5 py-12"><div className="overflow-hidden rounded-[2rem] bg-[#0B1F3A] p-6 text-white shadow-xl sm:p-10"><div className="mx-auto max-w-3xl text-center"><span className="inline-flex rounded-full bg-cyan-400/10 px-4 py-2 text-xs font-bold tracking-[.14em] text-cyan-300">SMART PRODUCT FINDER</span><h1 className="mt-5 text-3xl font-black sm:text-4xl">ไม่แน่ใจว่าจะเลือกอะไร? ให้เราช่วยแนะนำ</h1><p className="mt-3 text-sm leading-7 text-slate-300">เลือกเป้าหมาย งบประมาณ และห้องที่ต้องการ ระบบจะคัดสินค้าที่เหมาะกับคุณจากรายการในร้าน</p></div><div className="mt-9 grid gap-4 lg:grid-cols-3"><fieldset className="rounded-2xl border border-white/10 bg-white/5 p-5"><legend className="px-2 font-bold">1. ต้องการใช้งานด้านไหน</legend><div className="mt-3 grid gap-2">{[['security','🛡️ ความปลอดภัย'],['comfort','✨ ความสะดวกสบาย'],['energy','⚡ ประหยัดพลังงาน'],['kitchen','🍳 ห้องครัวอัจฉริยะ']].map(([value,label])=><button type="button" key={value} onClick={()=>setPurpose(value)} className={`rounded-xl border px-4 py-3 text-left text-sm font-bold ${purpose===value?'border-cyan-400 bg-cyan-400/15 text-cyan-200':'border-white/10 hover:bg-white/5'}`}>{label}</button>)}</div></fieldset><fieldset className="rounded-2xl border border-white/10 bg-white/5 p-5"><legend className="px-2 font-bold">2. งบประมาณต่อชิ้น</legend><div className="mt-3 grid gap-2">{[['1500','ไม่เกิน 1,500 บาท'],['3000','ไม่เกิน 3,000 บาท'],['6000','ไม่เกิน 6,000 บาท'],['999999','ไม่จำกัดงบ']].map(([value,label])=><button type="button" key={value} onClick={()=>setBudget(value)} className={`rounded-xl border px-4 py-3 text-left text-sm font-bold ${budget===value?'border-blue-400 bg-blue-500/20 text-blue-200':'border-white/10 hover:bg-white/5'}`}>{label}</button>)}</div></fieldset><fieldset className="rounded-2xl border border-white/10 bg-white/5 p-5"><legend className="px-2 font-bold">3. ต้องการใช้ในห้องไหน</legend><div className="mt-3 grid grid-cols-2 gap-2">{['ทุกห้อง',...rooms].map(value=><button type="button" key={value} onClick={()=>setSelectedRoom(value)} className={`rounded-xl border px-3 py-3 text-sm font-bold ${selectedRoom===value?'border-cyan-400 bg-cyan-400/15 text-cyan-200':'border-white/10 hover:bg-white/5'}`}>{value}</button>)}</div></fieldset></div><div className="mt-7 text-center"><button type="button" onClick={()=>setSearched(true)} className="rounded-xl bg-blue-600 px-8 py-4 font-bold text-white shadow-lg hover:bg-blue-500">ค้นหาสินค้าที่ใช่สำหรับคุณ →</button></div></div>{searched&&<div className="mt-12"><Title title="สินค้าที่แนะนำสำหรับคุณ" subtitle={recommendations.length?`พบ ${recommendations.length} รายการที่ตรงกับตัวเลือกของคุณ`:'ยังไม่พบสินค้าที่ตรงทุกเงื่อนไข ลองเพิ่มงบประมาณหรือเลือกทุกห้อง'}/>{recommendations.length?<div className="grid gap-5 sm:grid-cols-2 lg:grid-cols-4">{recommendations.map(product=><ProductCard key={product.id} product={product} onAdd={onAdd} favorite={favorites.includes(product.id)} onFavorite={onFavorite}/>)}</div>:<div className="rounded-2xl border border-dashed bg-white p-10 text-center"><p className="text-slate-500">ลองเปลี่ยนงบประมาณเป็น “ไม่จำกัดงบ” เพื่อดูตัวเลือกเพิ่มเติม</p></div>}</div>}</section>
}

function CheckoutPage({cart,clearCart}:{cart:Product[];clearCart:()=>void}){const[addresses,setAddresses]=useState<Address[]>([]),[addressId,setAddressId]=useState(''),[message,setMessage]=useState('');useEffect(()=>{fetch('/api/addresses').then(r=>r.json()).then(d=>{setAddresses(d.data||[]);const a=(d.data||[]).find(x=>x.is_default)||(d.data||[])[0];if(a)setAddressId(String(a.id))})},[]);const subtotal=cart.reduce((s,p)=>s+p.price,0),shipping=subtotal>=1500?0:80;async function order(){if(!cart.length){setMessage('ตะกร้าว่างเปล่า');return}if(!addressId){setMessage('กรุณาเพิ่มและเลือกที่อยู่จัดส่ง');return}const grouped=Object.values(cart.reduce((m,p)=>(m[p.id]=m[p.id]||{productId:p.id,quantity:0},m[p.id].quantity++,m),{}));const r=await fetch('/api/orders',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({items:grouped,addressId:Number(addressId)})});const d=await r.json();if(!r.ok){setMessage(d.error);return}clearCart();window.location.assign(`/orders/${d.data.orderNumber}`)}return <section className="mx-auto max-w-5xl px-5 py-12"><Title title="ชำระเงิน" subtitle="เลือกที่อยู่และยืนยันคำสั่งซื้อ"/><div className="grid gap-6 lg:grid-cols-[1fr_360px]"><div className="rounded-3xl border bg-white p-6"><h2 className="font-bold">ที่อยู่จัดส่ง</h2>{addresses.length?<select value={addressId} onChange={e=>setAddressId(e.target.value)} className="mt-4 w-full rounded-xl border p-3">{addresses.map(a=><option key={a.id} value={a.id}>{a.label} — {a.address_line} {a.province}</option>)}</select>:<p className="mt-4 rounded-xl bg-amber-50 p-4 text-sm">ยังไม่มีที่อยู่ กรุณา <a href="/profile" className="font-bold text-blue-600">เพิ่มที่อยู่ในโปรไฟล์</a></p>}<h2 className="mt-7 font-bold">สินค้า</h2>{cart.map((p,i)=><div key={i} className="mt-3 flex justify-between border-t pt-3 text-sm"><span>{p.name}</span><b>฿{p.price.toLocaleString()}</b></div>)}</div><aside className="rounded-3xl bg-[#0B1F3A] p-6 text-white"><h2 className="text-xl font-bold">ยอดชำระ</h2><p className="mt-5 flex justify-between"><span>สินค้า</span><b>฿{subtotal.toLocaleString()}</b></p><p className="mt-2 flex justify-between"><span>จัดส่ง</span><b>{shipping?`฿${shipping}`:'ฟรี'}</b></p><p className="mt-5 flex justify-between border-t border-white/20 pt-5"><b>รวม</b><b className="text-2xl text-cyan-300">฿{(subtotal+shipping).toLocaleString()}</b></p>{message&&<p className="mt-4 rounded-xl bg-red-500/20 p-3 text-sm">{message}</p>}<button onClick={order} className="mt-5 w-full rounded-xl bg-blue-600 py-4 font-bold">ยืนยันคำสั่งซื้อ</button></aside></div></section>}

function CheckoutPageV2({cart,clearCart}:{cart:Product[];clearCart:()=>void}){
  const[addresses,setAddresses]=useState<Address[]>([]),[addressId,setAddressId]=useState(''),[message,setMessage]=useState(''),[coupon,setCoupon]=useState(''),[paymentMethod,setPaymentMethod]=useState('PROMPTPAY'),[qrImage,setQrImage]=useState(''),[promptPayConfirmed,setPromptPayConfirmed]=useState(false),[walletProvider,setWalletProvider]=useState('TrueMoney Wallet'),[walletPhone,setWalletPhone]=useState(''),[otpSent,setOtpSent]=useState(false),[otp,setOtp]=useState(''),[card,setCard]=useState({name:'',number:'',expiry:'',cvc:''}),[submitting,setSubmitting]=useState(false);
  useEffect(()=>{setCoupon(localStorage.getItem('smart-home-coupon')||'');fetch('/api/addresses').then(r=>r.json()).then(d=>{setAddresses(d.data||[]);const a=(d.data||[]).find(x=>x.is_default)||(d.data||[])[0];if(a)setAddressId(String(a.id))})},[]);
  const subtotal=cart.reduce((sum,product)=>sum+product.price,0),discount=coupon.toUpperCase()==='SMART10'?Math.round(subtotal*.1):0,shipping=subtotal>=1500?0:80,total=subtotal-discount+shipping;
  const lines=Object.values(cart.reduce((map,product)=>{map[product.id]=map[product.id]||{product,quantity:0};map[product.id].quantity++;return map},{}));
  useEffect(()=>{if(paymentMethod!=='PROMPTPAY')return;const payload=`SMART-HOME-STORE|PROMPTPAY-DEMO|AMOUNT:${total.toFixed(2)}|REF:${Date.now().toString().slice(-8)}`;QRCode.toDataURL(payload,{width:260,margin:1,color:{dark:'#0B1F3A',light:'#FFFFFF'}}).then(setQrImage).catch(()=>setQrImage(''))},[paymentMethod,total]);
  function validatePayment(){if(paymentMethod==='CARD'){const digits=card.number.replace(/\D/g,'');if(card.name.trim().length<2||digits.length<16||!/^(0[1-9]|1[0-2])\/\d{2}$/.test(card.expiry)||!/^\d{3,4}$/.test(card.cvc)){return 'กรุณากรอกข้อมูลบัตรให้ครบและถูกต้อง'}}if(paymentMethod==='WALLET'&&(!/^0\d{8,9}$/.test(walletPhone)||!otpSent||!/^\d{6}$/.test(otp)))return 'กรุณาระบุเบอร์วอลเล็ตและยืนยัน OTP จำลอง 6 หลัก';if(paymentMethod==='PROMPTPAY'&&!promptPayConfirmed)return 'กรุณายืนยันว่าได้สแกน QR พร้อมเพย์แล้ว';return ''}
  async function order(){setMessage('');if(!cart.length){setMessage('ตะกร้าว่างเปล่า');return}if(!addressId){setMessage('กรุณาเพิ่มและเลือกที่อยู่จัดส่ง');return}const paymentError=validatePayment();if(paymentError){setMessage(paymentError);return}setSubmitting(true);const grouped=lines.map(line=>({productId:line.product.id,quantity:line.quantity}));const r=await fetch('/api/orders',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({items:grouped,addressId:Number(addressId),coupon,paymentMethod,paymentProvider:paymentMethod==='WALLET'?walletProvider:paymentMethod==='PROMPTPAY'?'PromptPay':'Credit/Debit Card'})});const d=await r.json();if(!r.ok){setMessage(d.error||'ไม่สามารถชำระเงินได้');setSubmitting(false);return}localStorage.removeItem('smart-home-coupon');clearCart();window.location.assign(`/orders/${d.data.orderNumber}`)}
  const inputClass='w-full rounded-xl border border-slate-200 bg-slate-50 px-4 py-3 text-sm outline-none focus:border-blue-500 focus:ring-2 focus:ring-blue-100';
  return <section className="mx-auto max-w-6xl px-5 py-12"><Title title="ชำระเงินอย่างปลอดภัย" subtitle="ตรวจสอบสินค้า เลือกที่อยู่ และเลือกวิธีชำระเงินที่สะดวก"/><div className="grid gap-7 lg:grid-cols-[1fr_380px]"><div className="space-y-6"><div className="minimal-card rounded-3xl p-6"><div className="flex items-center justify-between"><h2 className="text-lg font-bold">1. ที่อยู่จัดส่ง</h2><a href="/profile" className="text-sm font-bold text-blue-600">จัดการที่อยู่</a></div>{addresses.length?<select value={addressId} onChange={e=>setAddressId(e.target.value)} className={`${inputClass} mt-4`}>{addresses.map(address=><option key={address.id} value={address.id}>{address.label} — {address.recipient_name}, {address.address_line} {address.province}</option>)}</select>:<p className="mt-4 rounded-xl bg-amber-50 p-4 text-sm text-amber-800">ยังไม่มีที่อยู่ กรุณา <a href="/profile" className="font-bold underline">เพิ่มที่อยู่ในโปรไฟล์</a></p>}</div><div className="minimal-card rounded-3xl p-6"><h2 className="text-lg font-bold">2. วิธีชำระเงิน</h2><p className="mt-1 text-xs text-slate-500">ระบบจำลองสำหรับมินิโปรเจกต์ ไม่ตัดเงินจริงและไม่บันทึกเลขบัตร</p><div className="mt-5 grid gap-3 sm:grid-cols-3">{[['PROMPTPAY','▦','พร้อมเพย์ QR'],['CARD','▰','บัตรเครดิต/เดบิต'],['WALLET','◉','วอลเล็ต']].map(([value,icon,label])=><button type="button" key={value} onClick={()=>{setPaymentMethod(value);setMessage('')}} className={`rounded-2xl border p-4 text-left transition ${paymentMethod===value?'border-blue-600 bg-blue-50 ring-2 ring-blue-100':'border-slate-200 hover:border-blue-300'}`}><span className="text-2xl" aria-hidden="true">{icon}</span><b className="mt-2 block text-sm">{label}</b></button>)}</div>{paymentMethod==='PROMPTPAY'&&<div className="mt-5 grid items-center gap-5 rounded-2xl border border-blue-100 bg-blue-50/60 p-5 sm:grid-cols-[220px_1fr]">{qrImage?<img src={qrImage} alt={`QR พร้อมเพย์ ยอด ${total.toLocaleString()} บาท`} className="mx-auto w-full max-w-[220px] rounded-xl bg-white p-3 shadow-sm"/>:<div className="aspect-square animate-pulse rounded-xl bg-slate-200"/>}<div><span className="rounded-full bg-blue-600 px-3 py-1 text-xs font-bold text-white">PROMPTPAY</span><h3 className="mt-4 text-xl font-bold">สแกนเพื่อชำระ ฿{total.toLocaleString()}</h3><p className="mt-2 text-sm leading-6 text-slate-600">บัญชีร้านตัวอย่าง Smart Home Store<br/>QR นี้ใช้เพื่อสาธิตขั้นตอนเท่านั้น</p><label className="mt-4 flex cursor-pointer gap-3 rounded-xl bg-white p-3 text-sm"><input type="checkbox" checked={promptPayConfirmed} onChange={e=>setPromptPayConfirmed(e.target.checked)} className="h-5 w-5 accent-blue-600"/><span>ฉันสแกนและชำระเงินแล้ว (จำลอง)</span></label></div></div>}{paymentMethod==='CARD'&&<div className="mt-5 grid gap-4 rounded-2xl border bg-slate-50 p-5 sm:grid-cols-2"><label className="text-sm font-bold sm:col-span-2">ชื่อบนบัตร<input value={card.name} onChange={e=>setCard({...card,name:e.target.value})} autoComplete="cc-name" placeholder="JAKKARAT KAEWPECH" className={`${inputClass} mt-2 bg-white`}/></label><label className="text-sm font-bold sm:col-span-2">หมายเลขบัตร<input value={card.number} onChange={e=>setCard({...card,number:e.target.value.replace(/\D/g,'').slice(0,16).replace(/(.{4})/g,'$1 ').trim()})} inputMode="numeric" autoComplete="cc-number" placeholder="4242 4242 4242 4242" className={`${inputClass} mt-2 bg-white`}/></label><label className="text-sm font-bold">วันหมดอายุ<input value={card.expiry} onChange={e=>setCard({...card,expiry:e.target.value.replace(/[^\d/]/g,'').slice(0,5)})} autoComplete="cc-exp" placeholder="MM/YY" className={`${inputClass} mt-2 bg-white`}/></label><label className="text-sm font-bold">CVC<input value={card.cvc} onChange={e=>setCard({...card,cvc:e.target.value.replace(/\D/g,'').slice(0,4)})} type="password" inputMode="numeric" autoComplete="cc-csc" placeholder="123" className={`${inputClass} mt-2 bg-white`}/></label><p className="sm:col-span-2 text-xs text-slate-500">🔒 ข้อมูลบัตรใช้ตรวจรูปแบบในหน้านี้เท่านั้น และจะไม่ถูกส่งไปยังฐานข้อมูล</p></div>}{paymentMethod==='WALLET'&&<div className="mt-5 grid gap-4 rounded-2xl border bg-slate-50 p-5 sm:grid-cols-2"><label className="text-sm font-bold">ผู้ให้บริการ<select value={walletProvider} onChange={e=>setWalletProvider(e.target.value)} className={`${inputClass} mt-2 bg-white`}><option>TrueMoney Wallet</option><option>LINE Pay</option><option>ShopeePay</option></select></label><label className="text-sm font-bold">เบอร์โทรวอลเล็ต<input value={walletPhone} onChange={e=>setWalletPhone(e.target.value.replace(/\D/g,'').slice(0,10))} inputMode="numeric" placeholder="0812345678" className={`${inputClass} mt-2 bg-white`}/></label><button type="button" onClick={()=>{if(/^0\d{8,9}$/.test(walletPhone)){setOtpSent(true);setMessage('ส่งรหัส OTP จำลองแล้ว ใช้เลข 123456 เพื่อทดสอบ')}else setMessage('กรุณากรอกเบอร์โทรให้ถูกต้อง')}} className="rounded-xl border border-blue-200 bg-white px-4 py-3 text-sm font-bold text-blue-600">ส่ง OTP (จำลอง)</button>{otpSent&&<label className="text-sm font-bold">รหัส OTP<input value={otp} onChange={e=>setOtp(e.target.value.replace(/\D/g,'').slice(0,6))} inputMode="numeric" placeholder="123456" className={`${inputClass} mt-2 bg-white`}/></label>}</div>}</div><div className="minimal-card rounded-3xl p-6"><h2 className="text-lg font-bold">3. สินค้าในคำสั่งซื้อ</h2>{lines.map(line=><div key={line.product.id} className="mt-4 flex items-center gap-4 border-t border-slate-100 pt-4"><img src={line.product.image} alt="" className="h-14 w-14 rounded-xl bg-slate-50 object-contain p-1"/><div className="min-w-0 flex-1"><b className="block truncate text-sm">{line.product.name}</b><span className="text-xs text-slate-500">จำนวน {line.quantity}</span></div><b className="text-sm">฿{(line.product.price*line.quantity).toLocaleString()}</b></div>)}</div></div><aside className="h-fit rounded-3xl bg-[#0B1F3A] p-7 text-white shadow-xl lg:sticky lg:top-28"><h2 className="text-xl font-bold">สรุปยอดชำระ</h2><div className="mt-6 space-y-3 text-sm text-slate-300"><p className="flex justify-between"><span>สินค้า ({cart.length} ชิ้น)</span><b className="text-white">฿{subtotal.toLocaleString()}</b></p>{discount>0&&<p className="flex justify-between text-emerald-300"><span>คูปอง SMART10</span><b>-฿{discount.toLocaleString()}</b></p>}<p className="flex justify-between"><span>ค่าจัดส่ง</span><b className="text-white">{shipping?`฿${shipping}`:'ฟรี'}</b></p></div><p className="mt-6 flex justify-between border-t border-white/15 pt-5"><b>ยอดสุทธิ</b><b className="text-2xl text-cyan-300">฿{total.toLocaleString()}</b></p>{message&&<p role="status" className={`mt-4 rounded-xl p-3 text-sm ${message.includes('OTP')?'bg-blue-500/20 text-blue-100':'bg-red-500/20 text-red-100'}`}>{message}</p>}<button disabled={submitting||!cart.length} onClick={order} className="mt-6 w-full rounded-xl bg-blue-600 py-4 font-bold shadow-lg hover:bg-blue-500 disabled:cursor-not-allowed disabled:bg-slate-600">{submitting?'กำลังยืนยัน...':'ยืนยันและชำระเงิน'}</button><p className="mt-4 text-center text-[11px] leading-5 text-slate-400">การชำระเงินทั้งหมดเป็นการจำลอง ไม่มีการเรียกเก็บเงินจริง</p></aside></div></section>
}

function OrderPage({number}:{number:string}){const[order,setOrder]=useState<any>(null);useEffect(()=>{fetch(`/api/orders?orderNumber=${encodeURIComponent(number)}`).then(r=>r.json()).then(d=>setOrder(d.data?.[0]||false))},[number]);if(order===null)return <section className="state-page"><span className="state-spinner"/>กำลังโหลดคำสั่งซื้อ…</section>;if(!order)return <section className="state-page"><b>ไม่พบคำสั่งซื้อ</b><a href="/products">กลับไปเลือกสินค้า</a></section>;const paymentLabel={PROMPTPAY:'พร้อมเพย์ QR',CARD:'บัตรเครดิต/เดบิต',WALLET:'วอลเล็ต'}[order.payment_method]||'ไม่ระบุ',statusLabel={PENDING_PAYMENT:'รอชำระเงิน',PAID:'ชำระแล้ว',PREPARING:'กำลังเตรียม',SHIPPING:'กำลังจัดส่ง',DELIVERED:'ส่งสำเร็จ',CANCELLED:'ยกเลิก'}[order.status]||order.status,steps=['PAID','PREPARING','SHIPPING','DELIVERED'],current=steps.indexOf(order.status),cancelled=order.status==='CANCELLED';return <section className="order-page"><Title title={`คำสั่งซื้อ ${order.order_number}`} subtitle="ติดตามสถานะได้ตั้งแต่ชำระเงินจนถึงรับสินค้า"/><div className="order-shell"><div className={cancelled?'order-state cancelled':'order-state'}><span>{cancelled?'ยกเลิกแล้ว':'กำลังดำเนินการ'}</span><b>{cancelled?'คำสั่งซื้อนี้ถูกยกเลิก':current===3?'จัดส่งสำเร็จ':current===2?'พัสดุกำลังเดินทาง':current===1?'ร้านกำลังเตรียมสินค้า':'ยืนยันการชำระเงินแล้ว'}</b><p>อัปเดตสถานะล่าสุดจากระบบร้านค้า</p></div><div className="order-track">{['ชำระเงินแล้ว','กำลังเตรียม','กำลังจัดส่ง','ส่งสำเร็จ'].map((label,index)=><div key={label} className={!cancelled&&index<=current?'complete':''}><span>{!cancelled&&index<=current?'✓':index+1}</span><b>{label}</b></div>)}</div><div className="order-summary"><div><span>ยอดรวม</span><b>{Number(order.grand_total).toLocaleString('th-TH',{style:'currency',currency:'THB'})}</b></div><div><span>ช่องทางชำระเงิน</span><b>{paymentLabel}</b><small>เลขอ้างอิง {order.payment_reference||'-'}</small></div><div><span>สถานะในระบบ</span><b>{statusLabel}</b></div></div></div></section>}

function SmartHomePreview(){
  const [brightness,setBrightness]=useState(72);
  const [scene,setScene]=useState(0);
  const scenes=['อ่านหนังสือ','พักผ่อน','กลางคืน'];
  const nextScene=()=>setScene(current=>(current+1)%scenes.length);
  return <section aria-label="แผงควบคุมบ้านอัจฉริยะ" className="mx-auto w-full max-w-[520px] rounded-[2rem] border border-cyan-300/20 bg-gradient-to-br from-slate-800/95 via-blue-950/95 to-slate-900/95 p-5 shadow-[0_24px_80px_rgba(0,200,255,.18)] sm:p-6">
    <div className="grid grid-cols-[1.12fr_.88fr] gap-4">
      <article data-testid="lighting-panel" className="row-span-2 flex min-h-[344px] flex-col rounded-2xl border border-blue-400/30 bg-gradient-to-b from-blue-900/90 to-slate-800 p-5 shadow-[0_16px_35px_rgba(0,0,0,.3)]">
        <div className="flex items-center justify-between"><b className="text-xs text-cyan-300">LIVING ROOM</b><button type="button" onClick={nextScene} aria-label="เปลี่ยนโหมดแสง" title="เปลี่ยนโหมดแสง" className="rounded-lg px-2 py-1 text-xl leading-none text-white transition hover:bg-white/10">•••</button></div>
        <button type="button" onClick={()=>setBrightness(value=>value===100?35:100)} aria-label="เปิดหรือหรี่ไฟ" className="group grid flex-1 place-items-center rounded-2xl">
          <span aria-hidden="true" className="text-8xl transition duration-300 group-hover:scale-105" style={{opacity:.45+brightness/180,filter:`drop-shadow(0 0 ${14+brightness/4}px rgba(255,190,55,${.25+brightness/140}))`}}>💡</span>
        </button>
        <div><b className="text-lg text-white">Smart Lighting</b><p className="mt-1 text-xs text-slate-300"><span className="font-bold text-cyan-300">{scenes[scene]}</span> · ความสว่าง {brightness}%</p>
          <div className="mt-5 flex items-center gap-3 text-slate-400"><span aria-hidden="true">☼</span><input aria-label="ปรับความสว่าง" type="range" min="0" max="100" value={brightness} onChange={event=>setBrightness(Number(event.target.value))} className="h-1.5 flex-1 cursor-pointer accent-cyan-400"/><span aria-hidden="true" className="text-lg">☀</span></div>
        </div>
      </article>
      <article className="flex min-h-[162px] flex-col rounded-2xl border border-blue-300/20 bg-gradient-to-br from-blue-600 to-blue-800 p-4 shadow-[0_16px_35px_rgba(0,0,0,.3)]">
        <div className="flex items-start justify-between"><span aria-hidden="true" className="text-5xl">📷</span><a href="/rooms" aria-label="ดูอุปกรณ์รักษาความปลอดภัยหน้าบ้าน" className="grid h-7 w-7 place-items-center rounded-full bg-emerald-400 text-sm text-white hover:scale-110">✓</a></div>
        <b className="mt-3 text-white">บ้านปลอดภัย</b><a href="/products?category=Smart%20Camera" className="mt-2 w-fit rounded-lg border border-white/20 bg-blue-950/25 px-3 py-1.5 text-xs text-white hover:bg-white/15">ดูกล้อง →</a>
      </article>
      <a href="/products?category=Smart%20Sensor" aria-label="ดูสินค้าเซนเซอร์อุณหภูมิ" className="group min-h-[162px] rounded-2xl border border-blue-300/20 bg-gradient-to-br from-slate-800 to-blue-950 p-4 shadow-[0_16px_35px_rgba(0,0,0,.3)] hover:-translate-y-1">
        <div className="flex items-center justify-between"><span aria-hidden="true" className="text-4xl">🌡️</span><b className="text-4xl text-white">24°</b></div><p className="text-right text-[11px] text-slate-300">อุณหภูมิภายใน</p>
        <div aria-hidden="true" className="relative mt-3 h-10 overflow-hidden border-b border-cyan-300/20"><div className="absolute inset-0 bg-cyan-400/20 [clip-path:polygon(0_88%,14%_80%,28%_48%,42%_70%,58%_28%,72%_56%,88%_24%,100%_36%,100%_100%,0_100%)] transition group-hover:bg-cyan-300/30"></div><div className="absolute inset-x-0 bottom-1 h-px rotate-[-4deg] bg-cyan-300 shadow-[0_0_8px_#22d3ee]"></div></div>
      </a>
    </div>
  </section>
}

function NewsletterSignup({user}:{user:User|null}){
  const[loading,setLoading]=useState(false),[message,setMessage]=useState(''),[success,setSuccess]=useState(false);
  async function submit(event){
    event.preventDefault();setLoading(true);setMessage('');setSuccess(false);
    const form=event.currentTarget;
    const values={
      ...Object.fromEntries(new FormData(form)),
      consent:(form.elements.namedItem('consent') as HTMLInputElement)?.checked===true,
    };
    try{
      const response=await fetch('/api/newsletter',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify(values)});
      const data=await response.json();
      setMessage(data.message||data.error||'ไม่สามารถสมัครรับข่าวสารได้');
      setSuccess(response.ok);
      if(response.ok&&!user)form.reset();
    }catch{
      setMessage('เชื่อมต่อระบบอีเมลไม่ได้ กรุณาลองใหม่');
    }finally{
      setLoading(false);
    }
  }
  return <section id="newsletter" className="newsletter-section">
    <div className="newsletter-shell">
      <div className="newsletter-copy">
        <span>SMART HOME NOTES</span>
        <h2>รับไอเดียดี ๆ<br/>ส่งตรงถึงอีเมล</h2>
        <p>อัปเดตสินค้าใหม่ เคล็ดลับจัดบ้านอัจฉริยะ และสิทธิพิเศษที่คัดสรรให้คุณ</p>
        <div><b>✓ สมัครฟรี</b><b>✓ ยกเลิกได้ทุกเมื่อ</b><b>✓ ไม่ส่งอีเมลรบกวน</b></div>
      </div>
      <form onSubmit={submit} className="newsletter-form">
        <p className="newsletter-eyebrow">สมัครรับข่าวสาร</p>
        <h3>เริ่มต้นบ้านที่ฉลาดกว่า</h3>
        <label>อีเมล<input name="email" defaultValue={user?.email||''} required type="email" maxLength={191} autoComplete="email" placeholder="name@example.com"/></label>
        <label className="newsletter-consent"><input name="consent" value="true" required type="checkbox"/><span>ฉันยินยอมให้ Smart Home Store ใช้อีเมลเพื่อส่งข่าวสาร สินค้าใหม่ และโปรโมชั่น โดยยกเลิกได้ทุกเมื่อ</span></label>
        <label className="newsletter-honeypot" aria-hidden="true">บริษัท<input name="company" tabIndex={-1} autoComplete="off"/></label>
        <button disabled={loading}>{loading?'กำลังสมัคร...':'สมัครรับข่าวสาร'} <span>→</span></button>
        {message&&<p role="status" className={success?'newsletter-message success':'newsletter-message error'}>{message}</p>}
        <small>เมื่อสมัครแล้ว ระบบจะส่งอีเมลต้อนรับให้คุณทันที</small>
      </form>
    </div>
  </section>
}

function HeroSection({query,setQuery}:{query:string;setQuery:(value:string)=>void}){
  return <section className="store-hero relative isolate overflow-hidden bg-[#F6F8FB] text-[#0B1F3A]">
    <div aria-hidden="true" className="absolute -left-32 top-12 h-80 w-80 rounded-full bg-blue-100/80 blur-[100px]"></div>
    <div aria-hidden="true" className="absolute right-[-10rem] top-[-8rem] h-[34rem] w-[34rem] rounded-full bg-cyan-100/70 blur-[120px]"></div>
    <div className="store-hero-inner relative mx-auto grid max-w-7xl items-center gap-12 px-5 py-16 lg:min-h-[660px] lg:grid-cols-[.86fr_1.14fr] lg:gap-16 lg:py-20">
      <div className="relative z-10">
        <div className="inline-flex items-center gap-2 rounded-full border border-blue-200 bg-white px-4 py-2 text-xs font-bold tracking-[.12em] text-blue-700 shadow-sm"><span className="h-2 w-2 rounded-full bg-cyan-400"></span>SMART HOME, SIMPLIFIED</div>
        <h1 className="mt-7 max-w-xl text-5xl font-black leading-[1.06] tracking-[-.035em] text-[#0B1F3A] sm:text-6xl lg:text-[4rem]">ชีวิตง่ายขึ้นด้วย<br/><span className="text-blue-600">เทคโนโลยี</span></h1>
        <p className="mt-6 max-w-lg text-base leading-8 text-slate-600 sm:text-lg">อุปกรณ์อัจฉริยะที่ออกแบบมาให้บ้านสะดวก ปลอดภัย และประหยัดพลังงานมากขึ้นในทุกวัน</p>
        <form onSubmit={event=>{event.preventDefault();location.assign(`/products?q=${encodeURIComponent(query)}`)}} className="mt-8 flex max-w-lg gap-2 rounded-2xl border border-slate-200 bg-white p-2 shadow-[0_14px_40px_rgba(15,23,42,.08)]">
          <label className="flex min-w-0 flex-1 items-center gap-3 px-3"><span aria-hidden="true" className="text-lg text-slate-400">⌕</span><input value={query} onChange={event=>setQuery(event.target.value)} placeholder="ค้นหาสินค้า Smart Home..." className="min-w-0 flex-1 bg-transparent py-3 text-slate-900 outline-none placeholder:text-slate-400"/></label><button className="rounded-xl bg-blue-600 px-6 font-bold text-white transition hover:-translate-y-0.5 hover:bg-blue-700">ค้นหา</button>
        </form>
        <div className="mt-6 flex flex-wrap items-center gap-3"><a href="/products" className="rounded-xl bg-[#0B1F3A] px-6 py-3.5 font-bold text-white shadow-[0_12px_28px_rgba(11,31,58,.18)] hover:-translate-y-1 hover:bg-blue-700">เลือกซื้อสินค้า <span className="ml-2">→</span></a><a href="/recommendations" className="rounded-xl bg-cyan-50 px-5 py-3.5 font-bold text-cyan-700 hover:bg-cyan-100">ช่วยแนะนำสินค้า</a><a href="/rooms" className="rounded-xl px-5 py-3.5 font-bold text-slate-700 hover:bg-white hover:text-blue-600">เลือกตามห้อง</a></div>
        <div className="mt-9 flex flex-wrap gap-x-6 gap-y-3 border-t border-slate-200 pt-6 text-sm text-slate-500"><span className="flex items-center gap-2"><b className="grid h-7 w-7 place-items-center rounded-full bg-emerald-100 text-emerald-600">✓</b>รับประกันสินค้า</span><span className="flex items-center gap-2"><b className="grid h-7 w-7 place-items-center rounded-full bg-blue-100 text-blue-600">✓</b>จัดส่งทั่วประเทศ</span></div>
      </div>
      <div className="store-visual relative mx-auto w-full max-w-[690px]">
        <div className="store-float-card float-security"><b>98%</b><span>บ้านปลอดภัย</span></div>
        <div className="store-float-card float-devices"><i></i><b>12 อุปกรณ์</b><span>ออนไลน์</span></div>
        <div className="relative overflow-hidden rounded-[2.5rem] bg-white p-2 shadow-[0_32px_90px_rgba(15,45,85,.18)] ring-1 ring-slate-200/80">
          <div className="relative aspect-[4/3] overflow-hidden rounded-[2rem]">
            <img src="/hero-minimal-smart-home.png" alt="ห้องนั่งเล่นมินิมอลพร้อมอุปกรณ์ Smart Home" className="h-full w-full object-cover"/>
            <div aria-hidden="true" className="absolute inset-x-0 bottom-0 h-40 bg-gradient-to-t from-slate-950/45 to-transparent"></div>
            <div className="absolute left-5 top-5 flex items-center gap-2 rounded-full bg-white/90 px-3.5 py-2 text-xs font-bold text-slate-700 shadow-lg backdrop-blur"><span className="h-2 w-2 rounded-full bg-emerald-400 shadow-[0_0_0_4px_rgba(52,211,153,.16)]"></span>บ้านพร้อมใช้งาน</div>
            <div className="absolute inset-x-5 bottom-5 flex items-end justify-between gap-4 text-white"><div><p className="text-xs font-bold tracking-[.14em] text-cyan-200">SMART LIVING</p><h2 className="mt-1 text-xl font-bold sm:text-2xl">ทุกอุปกรณ์ ทำงานร่วมกัน</h2></div><a href="/smart-home-sets" className="shrink-0 rounded-full bg-white px-4 py-2 text-xs font-bold text-[#0B1F3A] shadow-lg hover:-translate-y-0.5 hover:bg-cyan-50">ดูชุดสินค้า →</a></div>
          </div>
        </div>
        <div className="mt-4 grid grid-cols-3 gap-2 sm:gap-3">
          <a href="/products?category=Smart%20Lighting" className="minimal-card flex min-w-0 items-center justify-center gap-2 rounded-xl px-2 py-3 text-center hover:-translate-y-0.5 hover:border-blue-200"><span aria-hidden="true">💡</span><b className="truncate text-[10px] text-slate-700 sm:text-xs">Smart Lighting</b></a><a href="/products?category=Smart%20Camera" className="minimal-card flex min-w-0 items-center justify-center gap-2 rounded-xl px-2 py-3 text-center hover:-translate-y-0.5 hover:border-blue-200"><span aria-hidden="true">🛡️</span><b className="truncate text-[10px] text-slate-700 sm:text-xs">Security</b></a><a href="/products?category=Smart%20Plug" className="minimal-card flex min-w-0 items-center justify-center gap-2 rounded-xl px-2 py-3 text-center hover:-translate-y-0.5 hover:border-blue-200"><span aria-hidden="true">⚡</span><b className="truncate text-[10px] text-slate-700 sm:text-xs">Energy Saving</b></a>
        </div>
      </div>
    </div>
  </section>
}

export default function StoreApp({path,user}:{path:string;user:User|null}){
  const[products,setProducts]=useState<Product[]>(fallback),[cart,setCart]=useState<Product[]>([]),[favorites,setFavorites]=useState<number[]>([]),[query,setQuery]=useState(''),[category,setCategory]=useState('ทั้งหมด'),[room,setRoom]=useState('ห้องนอน'),[coupon,setCoupon]=useState('');
  useEffect(()=>{fetch('/api/products').then(r=>r.ok?r.json():Promise.reject()).then(d=>{if(d.data?.length){setProducts(d.data);setCart(current=>{const next=current.map(item=>d.data.find(p=>p.id===item.id)||item);localStorage.setItem('smart-home-cart',JSON.stringify(next));return next})}}).catch(()=>{});try{setCart(JSON.parse(localStorage.getItem('smart-home-cart')||'[]'));setFavorites(JSON.parse(localStorage.getItem('smart-home-favorites')||'[]'));const p=new URLSearchParams(location.search);setQuery(p.get('q')||'');setCategory(p.get('category')||'ทั้งหมด')}catch{}},[]);
  useEffect(()=>{if(path==='/cart')localStorage.setItem('smart-home-coupon',coupon)},[coupon,path]);
  function saveCart(next:Product[]){setCart(next);localStorage.setItem('smart-home-cart',JSON.stringify(next))}
  function add(p:Product){saveCart([...cart,p])}
  function setQuantity(product:Product,quantity:number){const without=cart.filter(item=>item.id!==product.id);saveCart(quantity>0?[...without,...Array.from({length:Math.min(quantity,product.stock)},()=>product)]:without)}
  function toggleFavorite(p:Product){const next=favorites.includes(p.id)?favorites.filter(id=>id!==p.id):[...favorites,p.id];setFavorites(next);localStorage.setItem('smart-home-favorites',JSON.stringify(next))}
  const header=<SiteHeader user={user} cartCount={cart.length}/>;
  const cards=(list:Product[])=>list.map(p=><ProductCard key={p.id} product={p} onAdd={add} favorite={favorites.includes(p.id)} onFavorite={toggleFavorite}/>);
  const filtered=useMemo(()=>products.filter(p=>(category==='ทั้งหมด'||p.category===category)&&(`${p.name} ${p.brand}`.toLowerCase().includes(query.toLowerCase()))),[products,category,query]);
  const cartLines=useMemo(()=>Object.values(cart.reduce((map,product)=>{map[product.id]=map[product.id]||{product,quantity:0};map[product.id].quantity++;return map},{})),[cart]);
  if(path==='/')return <main className="minimal-page">{header}<HeroSection query={query} setQuery={setQuery}/><section className="mx-auto max-w-7xl px-5 py-16"><Title title="ช้อปตามหมวดหมู่" subtitle="เลือกอุปกรณ์ตามการใช้งาน"/><div className="grid grid-cols-2 gap-3 sm:grid-cols-5 lg:grid-cols-10">{categories.map(([icon,name])=><a key={name} href={`/products?category=${encodeURIComponent(name)}`} className="minimal-card group rounded-2xl p-4 text-center hover:-translate-y-1 hover:border-blue-200"><span className="mx-auto grid h-11 w-11 place-items-center rounded-xl bg-blue-50 text-2xl transition group-hover:bg-blue-100">{icon}</span><b className="mt-3 block text-[11px] text-slate-700">{name}</b></a>)}</div><div className="mt-16"><Title title="สินค้ายอดนิยม" subtitle="ภาพสินค้าจริงพร้อมรายละเอียด"/><div className="grid gap-5 sm:grid-cols-2 lg:grid-cols-4">{cards(products.slice(0,4))}</div></div></section><NewsletterSignup user={user}/></main>;
  if(path==='/register')return <main className="minimal-page">{header}<section className="mx-auto max-w-6xl px-5 py-12"><RegisterForm/></section></main>;
  if(path==='/login')return <main className="minimal-page">{header}<section className="auth-page"><LoginForm/></section></main>;
  if(path==='/terms')return <main>{header}<LegalPage kind="terms"/></main>;
  if(path==='/privacy')return <main>{header}<LegalPage kind="privacy"/></main>;
  if(path==='/profile'&&user)return <main>{header}<ProfilePage user={user}/></main>;
  if(path.startsWith('/admin')&&user?.role==='ADMIN')return <main className="min-h-screen bg-slate-100"><AdminPage/></main>;
  if(path==='/products'||path==='/categories')return <main>{header}<section className="mx-auto max-w-7xl px-5 py-12"><Title title="สินค้าทั้งหมด" subtitle="ค้นหาและเลือกอุปกรณ์ที่เข้ากับบ้านของคุณ"/><div className="mb-7 flex flex-wrap gap-3"><input value={query} onChange={e=>setQuery(e.target.value)} placeholder="ค้นหาสินค้า..." className="min-w-64 flex-1 rounded-xl border bg-white px-4 py-3"/><select value={category} onChange={e=>setCategory(e.target.value)} className="rounded-xl border bg-white px-4"><option>ทั้งหมด</option>{[...new Set(products.map(p=>p.category))].map(x=><option key={x}>{x}</option>)}</select></div><div className="grid gap-5 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4">{cards(filtered)}</div>{!filtered.length&&<p className="rounded-2xl bg-white p-8 text-center text-slate-500">ไม่พบสินค้าที่ค้นหา</p>}</section></main>;
  if(path==='/recommendations')return <main className="minimal-page">{header}<RecommendationPage products={products} onAdd={add} favorites={favorites} onFavorite={toggleFavorite}/></main>;
  if(path.startsWith('/products/')){const p=products.find(x=>x.id===Number(path.split('/').pop()))||fallback.find(x=>x.id===Number(path.split('/').pop()));return <main>{header}{p?<section className="mx-auto grid max-w-6xl gap-10 px-5 py-14 md:grid-cols-2"><div className="aspect-square rounded-[2rem] bg-white"><img src={p.image} alt={p.name} className="h-full w-full object-contain p-8"/></div><div><p className="font-bold text-blue-600">{p.category}</p><h1 className="mt-3 text-4xl font-bold">{p.name}</h1><p className="mt-3 text-amber-500">★★★★★ {p.rating}</p><p className="mt-6 text-3xl font-bold text-blue-600">฿{p.price.toLocaleString()} <del className="text-lg text-slate-400">฿{p.old.toLocaleString()}</del></p><p className="mt-6 leading-7 text-slate-600">{p.description} ติดตั้งง่าย รองรับระบบ Smart Home และรับประกันสินค้า 2 ปี</p><div className="mt-6 rounded-xl bg-green-50 p-4 text-sm text-green-700">● มีสินค้า {p.stock} ชิ้น</div><button onClick={()=>add(p)} className="mt-6 w-full rounded-xl bg-blue-600 py-4 font-bold text-white">เพิ่มลงตะกร้า</button></div></section>:<p className="p-12 text-center">ไม่พบสินค้า</p>}</main>}
  if(path==='/rooms')return <main>{header}<section className="mx-auto max-w-7xl px-5 py-12"><Title title="เลือกตามห้อง" subtitle="ค้นหาอุปกรณ์ที่เหมาะกับพื้นที่นั้น"/><div className="flex flex-wrap gap-3">{rooms.map(r=><button key={r} onClick={()=>setRoom(r)} className={`rounded-full px-5 py-3 text-sm font-bold ${room===r?'bg-blue-600 text-white':'border bg-white'}`}>{r}</button>)}</div><div className="mt-9 grid gap-5 sm:grid-cols-2 lg:grid-cols-4">{cards(products.filter(p=>p.room===room))}</div></section></main>;
  if(path==='/smart-home-sets')return <main className="minimal-page">{header}<section className="mx-auto max-w-6xl px-5 py-12"><Title title="Smart Home Set" subtitle="ซื้อเป็นชุด เริ่มต้นง่ายและประหยัดกว่า"/><div className="grid gap-6 md:grid-cols-2">{[['Starter Smart Home Set',[products[0],products[3]].filter(Boolean)],['Security Smart Home Set',[products[1],products[2]].filter(Boolean)]].map(([name,set],index)=><article key={name as string} className="minimal-card overflow-hidden rounded-2xl"><div className={`h-1.5 ${index===0?'bg-blue-500':'bg-cyan-500'}`}></div><div className="p-8"><span className="text-[11px] font-bold tracking-[.15em] text-blue-600">READY-TO-USE SET</span><b className="mt-3 block text-2xl text-slate-900">{name}</b><p className="mt-4 text-sm leading-7 text-slate-500">{(set as Product[]).map(p=>p.name).join(' + ')}</p><button onClick={()=>saveCart([...cart,...set as Product[]])} className="mt-6 rounded-full bg-slate-900 px-5 py-3 text-sm font-bold text-white hover:bg-blue-600">เพิ่มทั้งชุดลงตะกร้า</button></div></article>)}</div></section></main>;
  if(path==='/favorites')return <main>{header}<section className="mx-auto max-w-7xl px-5 py-12"><Title title="รายการโปรด" subtitle="สินค้าที่คุณบันทึกไว้ในอุปกรณ์นี้"/><div className="grid gap-5 sm:grid-cols-2 lg:grid-cols-4">{cards(products.filter(p=>favorites.includes(p.id)))}</div>{!favorites.length&&<p className="rounded-2xl bg-white p-8 text-center">ยังไม่มีสินค้าโปรด</p>}</section></main>;
  if(path==='/promotions')return <main>{header}<section className="mx-auto max-w-7xl px-5 py-12"><Title title="โปรโมชั่นพิเศษ" subtitle="สินค้าราคาพิเศษสำหรับวันนี้"/><div className="grid gap-5 sm:grid-cols-2 lg:grid-cols-4">{cards(products.filter(p=>p.old>p.price))}</div></section></main>;
  if(path==='/cart'){const subtotal=cart.reduce((s,p)=>s+p.price,0),discount=coupon.toUpperCase()==='SMART10'?Math.round(subtotal*.1):0,shipping=subtotal>=1500?0:80;return <main>{header}<section className="mx-auto max-w-6xl px-5 py-12"><Title title="ตะกร้าสินค้า" subtitle={`${cartLines.length} รายการ · รวม ${cart.length} ชิ้น`}/><div className="grid gap-8 lg:grid-cols-[1fr_360px]"><div className="space-y-4">{cartLines.map(line=><article key={line.product.id} className="grid items-center gap-4 rounded-2xl border bg-white p-4 sm:grid-cols-[90px_1fr_auto]"><img src={line.product.image} alt={line.product.name} className="h-20 w-20 rounded-xl bg-slate-50 object-contain p-2"/><div className="min-w-0"><b className="block truncate">{line.product.name}</b><p className="mt-1 text-sm text-slate-400">พร้อมจัดส่ง · คงเหลือ {line.product.stock} ชิ้น</p><button onClick={()=>setQuantity(line.product,0)} className="mt-2 text-xs font-bold text-red-500 hover:underline">ลบสินค้า</button></div><div className="flex items-center justify-between gap-5 sm:block sm:text-right"><div className="inline-flex items-center rounded-full border border-slate-200 bg-slate-50 p-1"><button onClick={()=>setQuantity(line.product,line.quantity-1)} aria-label={`ลดจำนวน ${line.product.name}`} className="grid h-8 w-8 place-items-center rounded-full text-lg hover:bg-white">−</button><span className="min-w-9 text-center text-sm font-bold">{line.quantity}</span><button disabled={line.quantity>=line.product.stock} onClick={()=>setQuantity(line.product,line.quantity+1)} aria-label={`เพิ่มจำนวน ${line.product.name}`} className="grid h-8 w-8 place-items-center rounded-full text-lg hover:bg-white disabled:opacity-30">＋</button></div><b className="mt-3 block text-blue-600">฿{(line.product.price*line.quantity).toLocaleString()}</b></div></article>)}{!cart.length&&<div className="rounded-2xl border border-dashed bg-white p-10 text-center"><p className="text-slate-500">ตะกร้ายังว่างอยู่</p><a href="/products" className="mt-4 inline-flex rounded-xl bg-blue-600 px-5 py-3 text-sm font-bold text-white">เลือกซื้อสินค้า</a></div>}</div><aside className="h-fit rounded-3xl bg-[#0B1F3A] p-7 text-white shadow-xl lg:sticky lg:top-28"><h2 className="text-xl font-bold">สรุปคำสั่งซื้อ</h2><p className="mt-5 flex justify-between text-sm"><span>สินค้า ({cart.length} ชิ้น)</span><b>฿{subtotal.toLocaleString()}</b></p><p className="mt-2 flex justify-between text-sm"><span>ส่วนลด</span><b className="text-emerald-300">-฿{discount.toLocaleString()}</b></p><p className="mt-2 flex justify-between text-sm"><span>จัดส่ง</span><b>{shipping?`฿${shipping}`:'ฟรี'}</b></p><div className="mt-5 flex gap-2"><input value={coupon} onChange={e=>setCoupon(e.target.value)} placeholder="คูปอง SMART10" className="min-w-0 flex-1 rounded-xl border border-white/10 bg-white/10 p-3 text-sm outline-none placeholder:text-slate-400"/><button type="button" className="rounded-xl bg-white px-3 text-sm font-bold text-blue-600">ใช้</button></div><p className="mt-5 flex justify-between border-t border-white/20 pt-5"><b>รวม</b><b className="text-2xl text-cyan-300">฿{(subtotal-discount+shipping).toLocaleString()}</b></p><a href={user?'/checkout':'/login?returnTo=/checkout'} className={`mt-6 block rounded-xl py-4 text-center font-bold ${cart.length?'bg-blue-600 hover:bg-blue-500':'pointer-events-none bg-slate-600'}`}>ดำเนินการชำระเงิน</a></aside></div></section></main>}
  if(path==='/checkout'&&user)return <main>{header}<CheckoutPageV2 cart={cart} clearCart={()=>saveCart([])}/></main>;
  if(path.startsWith('/orders/')&&user)return <main>{header}<OrderPage number={path.split('/').pop()||''}/></main>;
  return <main>{header}<section className="mx-auto max-w-5xl px-5 py-20 text-center"><h1 className="text-4xl font-bold">ไม่พบหน้านี้</h1><a href="/" className="mt-6 inline-block text-blue-600">กลับหน้าหลัก</a></section></main>;
}
